import{c as g,g as l}from"./sheetsClient.Bc1rSthu.js";async function d(){const o=sessionStorage.getItem("btc_config"),n=sessionStorage.getItem("btc_config_time");if(o&&n&&Date.now()-parseInt(n)<3e5){const t=JSON.parse(o);window.dispatchEvent(new CustomEvent("btc:config-loaded",{detail:t}));return}try{const t=await g();let s=!1,a=!1;try{const{mods:c}=await l(),r=c.map(e=>e.name.toLowerCase());s=r.some(e=>e.includes("geyser")),a=r.some(e=>e.includes("viaversion")||e.includes("viabackwards")||e.includes("viarewind"))}catch{console.warn("No se pudieron leer los mods.")}const i={...t,isBedrock:s,isMultiVersion:a};sessionStorage.setItem("btc_config",JSON.stringify(i)),sessionStorage.setItem("btc_config_time",Date.now().toString()),window.dispatchEvent(new CustomEvent("btc:config-loaded",{detail:i}))}catch(t){console.error("Error cargando configuración:",t)}}document.addEventListener("DOMContentLoaded",d);document.addEventListener("astro:page-load",d);
